"use client";

import { useParams, notFound } from "next/navigation";
import Image from "next/image";
import Link from "next/link";
import { motion } from "framer-motion";
import { ArrowLeft, ArrowRight, ExternalLink } from "lucide-react";
import { portfolio } from "@/data/portfolio";
import { useLanguage } from "@/context/LanguageContext";
import CTABand from "@/components/sections/CTABand";

export default function PortfolioCaseStudy() {
  const { slug } = useParams();
  const { lang } = useLanguage();
  const isRTL = lang === "ar";

  const projectIndex = portfolio.findIndex((p) => p.slug === slug);
  
  if (projectIndex === -1) {
    notFound();
  }

  const project = portfolio[projectIndex];
  const nextProject = portfolio[(projectIndex + 1) % portfolio.length];

  return (
    <main className="min-h-screen bg-brand-black text-brand-white">
      {/* Section 1: Hero Image */}
      <section className="pt-36 pb-8 px-4 md:px-8 max-w-7xl mx-auto">
        <Link 
          href="/portfolio"
          className="inline-flex items-center gap-2 text-brand-gray2 hover:text-brand-primary transition-colors mb-6 group"
        >
          {isRTL ? (
            <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-1" />
          ) : (
            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
          )}
          <span>{isRTL ? "العودة للأعمال" : "Back to Portfolio"}</span>
        </Link>
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="relative w-full aspect-[16/9] lg:aspect-[21/9] rounded-2xl overflow-hidden"
        >
          <Image
            src={project.image}
            alt={project.title[lang]}
            fill
            className="object-cover"
            priority
          />
        </motion.div>
      </section>

      {/* Section 2: Project Meta */}
      <section className="px-4 md:px-8 py-12 max-w-7xl mx-auto">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="flex flex-col md:flex-row md:items-start justify-between gap-6 border-t border-brand-gray1/20 pt-8"
        >
          <div className="space-y-4">
            <div className="inline-block px-3 py-1 bg-brand-gray1/50 rounded-full text-brand-primary text-sm font-medium">
              {project.category[lang]}
            </div>
            <h1 className="text-3xl md:text-5xl font-bold">{project.title[lang]}</h1>
            <div className="flex flex-wrap items-center gap-6 text-brand-gray2 text-lg">
              <div><span className="font-semibold text-brand-white">{isRTL ? "العميل:" : "Client:"}</span> {project.client[lang]}</div>
              <div><span className="font-semibold text-brand-white">{isRTL ? "السنة:" : "Year:"}</span> {project.year}</div>
            </div>
          </div>
          {project.liveUrl && (
            <Link 
              href={project.liveUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-2 px-6 py-3 bg-brand-primary text-brand-black font-semibold rounded-full hover:bg-brand-primary/90 transition-colors shrink-0"
            >
              <span>{isRTL ? "زيارة المشروع المباشر" : "Visit Live Project"}</span>
              {isRTL ? <ArrowLeft className="w-4 h-4" /> : <ExternalLink className="w-4 h-4" />}
            </Link>
          )}
        </motion.div>
      </section>

      {/* Section 3: Challenge & Solution */}
      <section className="px-4 md:px-8 py-16 bg-brand-gray1/20">
        <div className="max-w-7xl mx-auto grid lg:grid-cols-2 gap-12 lg:gap-24">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="space-y-6"
          >
            <div className="text-brand-primary font-mono text-sm uppercase tracking-widest">
              {isRTL ? "التحدي" : "THE CHALLENGE"}
            </div>
            <p className="text-lg md:text-xl text-brand-gray2 leading-relaxed">
              {project.challenge[lang]}
            </p>
          </motion.div>
          
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.2 }}
            className="space-y-6"
          >
            <div className="text-brand-primary font-mono text-sm uppercase tracking-widest">
              {isRTL ? "الحل" : "THE SOLUTION"}
            </div>
            <p className="text-lg md:text-xl text-brand-gray2 leading-relaxed">
              {project.solution[lang]}
            </p>
          </motion.div>
        </div>
      </section>

      {/* Section 4: Results */}
      <section className="px-4 md:px-8 py-24 max-w-7xl mx-auto">
        <motion.h2 
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-2xl md:text-3xl font-bold uppercase text-center mb-16"
        >
          {isRTL ? "النتائج" : "THE RESULTS"}
        </motion.h2>
        <div className="grid grid-cols-1 md:flex md:flex-row justify-center gap-6">
          {project.results.map((result, idx) => (
            <motion.div
              key={idx}
              initial={{ opacity: 0, scale: 0.9 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ delay: idx * 0.1 }}
              className="flex-1 bg-brand-gray1/30 border border-brand-gray1/50 rounded-2xl p-8 flex flex-col items-center justify-center text-center max-w-sm mx-auto w-full"
            >
              <div className="text-4xl md:text-5xl font-bold text-brand-primary mb-2">{result.metric}</div>
              <div className="text-brand-gray2 text-sm">{result.label[lang]}</div>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Section 5: Image Gallery */}
      <section className="px-4 md:px-8 py-16 max-w-7xl mx-auto">
        <motion.h2 
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-2xl md:text-3xl font-bold uppercase text-center mb-16"
        >
          {isRTL ? "معرض الصور" : "PROJECT GALLERY"}
        </motion.h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {project.gallery.map((imgUrl, idx) => (
            <motion.div
              key={idx}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: idx * 0.1 }}
              className="relative aspect-[4/3] rounded-xl overflow-hidden group"
            >
              <Image
                src={imgUrl}
                alt={`${project.title[lang]} gallery image ${idx + 1}`}
                fill
                className="object-cover transition-transform duration-500 group-hover:scale-105"
              />
            </motion.div>
          ))}
        </div>
      </section>

      {/* Section 6: Next Project */}
      <section className="px-4 md:px-8 py-24 max-w-4xl mx-auto">
        <Link href={`/portfolio/${nextProject.slug}`} className="block group">
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="flex flex-col items-center text-center gap-6"
          >
            <div className="flex items-center gap-2 text-brand-primary text-lg font-medium">
              <span>{isRTL ? "المشروع التالي" : "Next Project"}</span>
              {isRTL ? (
                <ArrowLeft className="w-5 h-5 transition-transform group-hover:-translate-x-1" />
              ) : (
                <ArrowRight className="w-5 h-5 transition-transform group-hover:translate-x-1" />
              )}
            </div>
            <h3 className="text-4xl md:text-6xl font-bold group-hover:text-brand-gray2 transition-colors">
              {nextProject.title[lang]}
            </h3>
            <div className="relative w-full aspect-[21/9] rounded-2xl overflow-hidden mt-8 opacity-80 group-hover:opacity-100 transition-opacity duration-500">
               <Image
                src={nextProject.image}
                alt={nextProject.title[lang]}
                fill
                className="object-cover transition-transform duration-700 group-hover:scale-105"
              />
            </div>
          </motion.div>
        </Link>
      </section>

      {/* Section 7: CTA */}
      <CTABand />
    </main>
  );
}
